def _is_lexbfs_strict(order, adj, n):
    """Strict LexBFS check: for all a < b < c with ac in E and ab not in E,
    exists d < a with db in E and dc not in E, AND d is adjacent to a
    (i.e. d is a LexBFS parent of a).  This is the condition that the
    ordering is a valid LexBFS ordering (not just a valid LB ordering)."""
    for a in range(n):
        va = order[a]
        for b in range(a + 1, n):
            vb = order[b]
            if va in adj[vb]:
                continue
            for c in range(b + 1, n):
                vc = order[c]
                if va not in adj[vc]:
                    continue
                ok = False
                for d in range(a):
                    vd = order[d]
                    if vb in adj[vd] and vc not in adj[vd] and va in adj[vd]:
                        ok = True
                        break
                if not ok:
                    return False
